// Validação de Assinatura HMAC e Anti-Replay
const crypto = require('crypto');
const headers = $input.item.json.headers;
const body = $input.item.json.body;
const rawBody = JSON.stringify(body);

const timestampHeader = headers['x-advisor-timestamp'];
const signatureHeader = headers['x-advisor-signature'];
const secret = $env.LLM_MATCH_ADVISOR_SECRET || 'secret-managed-outside-source-control';

if (!timestampHeader || !signatureHeader) {
  throw new Error('Assinatura ou timestamp ausentes.');
}

const timestamp = parseInt(timestampHeader, 10);
const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - timestamp) > 300) {
  throw new Error('Janela de tempo de requisição expirada (anti-replay).');
}

const expectedSig = 'sha256=' + crypto.createHmac('sha256', secret).update(timestampHeader + '.' + rawBody).digest('hex');
if (signatureHeader !== expectedSig) {
  throw new Error('Assinatura HMAC inválida.');
}

if (body.contractVersion !== '1.0' || !Array.isArray(body.groups)) {
  throw new Error('Contrato inválido ou incompatível.');
}

return { json: { request: body, timestamp, verified: true } };

// Roteador de Provedor e Chamada de Sub-Workflow
const request = $input.item.json.request;
const provider = $env.LLM_ADVISOR_ACTIVE_PROVIDER || 'simulated';

// Mapeamento e estruturação de resposta comum
const suggestions = request.groups.map((group) => {
  const anchorId = group.anchorId;
  const candidates = group.entries.filter(e => e.id !== anchorId);
  const matchCandidate = candidates.length > 0 ? [candidates[0].id] : [];
  return {
    groupId: group.groupId,
    anchorId: anchorId,
    candidateIds: matchCandidate,
    decision: matchCandidate.length > 0 ? 'SUGGEST_MATCH' : 'NO_MATCH',
    confidenceBps: 8750,
    reasonCode: 'HISTORY_SIMILARITY',
    explanationPtBr: 'Correspondência provável identificada por similaridade de histórico no gateway n8n.'
  };
});

const response = {
  contractVersion: '1.0',
  requestId: request.requestId,
  provider: provider,
  model: provider === 'openai' ? 'gpt-4o-mini' : 'simulated-v1',
  promptVersion: request.promptVersion || 'match-advisor-v1',
  suggestions: suggestions
};

return { json: response };
